#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
#if USE_TEXTURE
  in vec2 uv0;
  uniform sampler2D cc_spriteTexture;
#endif
layout(std140) uniform Constant {
  vec4 outlineColor;
  vec4 innerGlowColor;
  vec2 textureSize;
  float outlineWidth;
  float glowIntensity;
  float glowSoftness;
  float innerGlowIntensity;
};
float getOutlineAlpha(vec2 uv, vec2 offset) {
  float alpha = 0.0;
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(-1.0, -1.0) * offset).a);
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(0.0, -1.0) * offset).a);
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(1.0, -1.0) * offset).a);
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(-1.0, 0.0) * offset).a);
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(1.0, 0.0) * offset).a);
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(-1.0, 1.0) * offset).a);
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(0.0, 1.0) * offset).a);
  alpha = max(alpha, CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(1.0, 1.0) * offset).a);
  return alpha;
}
float getGlowFactor(vec2 uv, vec2 offset, float width) {
  float maxGlow = 0.0;
  const int MAX_SAMPLES = 20;
  for (int i = 1; i <= MAX_SAMPLES; i++) {
    float dist = float(i);
    if (dist > width) break;
    float alpha = getOutlineAlpha(uv, offset * dist);
    float falloff = 1.0 - (dist / width);
    falloff = pow(falloff, 1.0 / max(glowSoftness, 0.1));
    maxGlow = max(maxGlow, alpha * falloff);
  }
  return maxGlow;
}
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    vec4 texColor = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
    float originalAlpha = texColor.a;
    o *= texColor;
    #if IS_GRAY
      float gray = 0.2126 * o.r + 0.7152 * o.g + 0.0722 * o.b;
      o.r = o.g = o.b = gray;
    #endif
    vec2 pixelOffset = 1.0 / textureSize;
    if (originalAlpha < 0.01) {
      float glowFactor = getGlowFactor(uv0, pixelOffset, outlineWidth);
      if (glowFactor > 0.01) {
        o.rgb = outlineColor.rgb;
        o.a = glowFactor * outlineColor.a * glowIntensity;
      }
    } else {
      o *= color;
      if (innerGlowIntensity > 0.01) {
        float edgeAlpha = 1.0 - getOutlineAlpha(uv0, pixelOffset * 2.0);
        if (edgeAlpha < 0.99) {
          float innerGlow = (1.0 - edgeAlpha) * innerGlowIntensity;
          o.rgb = mix(o.rgb, innerGlowColor.rgb, innerGlow * innerGlowColor.a);
        }
      }
    }
  #else
    o *= color;
  #endif
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

